defmodule RoomServer do
  use GenServer

  # Client API
  def start_link(room_id), do: GenServer.start_link(__MODULE__, room_id, name: via(room_id))
  def post(room_id, user, message), do: GenServer.cast(via(room_id), {:post, user, message})
  def messages(room_id), do: GenServer.call(via(room_id), :messages)
  defp via(room_id), do: room_id

  # Server callbacks
  @impl true
  def init(room_id), do: {:ok, %{room_id: room_id, messages: []}}

  @impl true
  def handle_cast({:post, user, message}, state) do
    {:noreply, %{state | messages: [{user, message} | state.messages]}}
  end

  @impl true
  def handle_call(:messages, _from, state) do
    {:reply, Enum.reverse(state.messages), state}
  end
end

